-- ============================================================================
-- Migration 010: rubric versioning + public.teams operational config
-- Spec: database/SQLMigration.md §3.4 (rubric_version column),
--       §3.6 (compute_overall_score signature), §6 (public.teams ops),
--       §3.19 (qa.rubric_versions write path + hard-fail validation),
--       §7.6 (migration ordering)
--
-- Three coupled additions:
--
--   1) qa.rubric_versions — archived rubric JSONs (sections +
--      scoring_prompt) per §3.19. Slug-style versioning, FK target for
--      qa.evaluations.rubric_version.
--
--   2) ALTER qa.evaluations to add rubric_version TEXT FK. Stamped at
--      Stage 1 from the team's active rubric_versions row.
--
--   3) ALTER public.teams to absorb operational config (company,
--      stats_config, gemini_config, excluded_test_agents, sheets_config,
--      updated_at) so the JSON file is fully DB-generable. Lightly
--      versioned via updated_at — see §6 versioning-split rationale.
--
-- The migration also SEEDS:
--   - qa.rubric_versions with sales_v1 + member_support_v1 (embedded
--     rubric_json extracted from the current config/teams/<team>.json
--     content at migration apply time).
--   - public.teams operational columns from the same JSON content.
--
-- From this migration onward, qa.rubric_versions IS the source of truth
-- for rubric configuration. The JSON files become generated export
-- artifacts (post-Wave-2 cutover); never read by application code once
-- the team_config.py refactor lands.
--
-- Reversible via 010_rubric_versioning_down.sql.
-- ============================================================================


-- ── (a) qa.rubric_versions — archived rubric JSONs (§3.19) ──────────────────

CREATE TABLE qa.rubric_versions (
    id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    rubric_version  TEXT NOT NULL UNIQUE,
    team_id         TEXT NOT NULL REFERENCES public.teams(id),
    -- Contains rubric_version (echo of column), sections array, and
    -- scoring_prompt. Pydantic-validate at API boundary per §3.19.1.
    rubric_json     JSONB NOT NULL,
    effective_from  TIMESTAMPTZ NOT NULL,
    effective_until TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_rubric_versions_team_effective
    ON qa.rubric_versions (team_id, effective_from DESC);


-- ── (b) ALTER qa.evaluations — add rubric_version FK (§3.4) ─────────────────

ALTER TABLE qa.evaluations
    ADD COLUMN rubric_version TEXT REFERENCES qa.rubric_versions(rubric_version);


-- ── (c) ALTER public.teams — absorb operational config (§6) ────────────────

ALTER TABLE public.teams
    ADD COLUMN company              TEXT,
    ADD COLUMN stats_config         JSONB,
    ADD COLUMN gemini_config        JSONB,
    ADD COLUMN excluded_test_agents TEXT[] NOT NULL DEFAULT '{}',
    ADD COLUMN sheets_config        JSONB,
    ADD COLUMN updated_at           TIMESTAMPTZ NOT NULL DEFAULT NOW();


